package dev.nezo.burmaldaholic.client.board;

import dev.nezo.burmaldaholic.Burmaldaholic;
import dev.nezo.burmaldaholic.core.ui.v2.board.BoardGeometry;
import net.minecraft.resources.Identifier;

/**
 * The board kit's atlases ({@code textures/entity/core/board/}, generated by {@code tools/assets/modules/board.mjs};
 * never hand-edited) and their UV maths.
 *
 * <ul>
 *   <li>{@code faces_w2.png} 512 × 256: card faces {@link #CARD_W} × {@link #CARD_H} texels, columns A 2 … 10 J Q K,
 *       rows ♠ ♥ ♦ ♣ (card id = rank index × 4 + suit, the W-atlas order); row 4 = backs (navy, burgundy, crimson,
 *       emerald, bastion, end).</li>
 *   <li>{@code chips_w.png} 128 × 64: per denomination column {@code d} ({@link BoardGeometry#DENOMS}) 16 px wide, the top
 *       disc at y 0 (16 × 16) and the side band of six stacked discs at y 16 (16 × 24, 4 px per disc).</li>
 *   <li>{@code felt_w_<shape>_<theme>.png}: the felt top with its rail, 64 texels per block, transparent outside the
 *       rounded shape; {@code rail_w_<theme>.png} 16 × 16: the apron wood.</li>
 *   <li>{@code holo_backing.png} 4 × 4 white: the text backing, tinted ink 70 % in code.</li>
 * </ul>
 */
public final class BoardTextures {
	public static final Identifier FACES = Burmaldaholic.id("textures/entity/core/board/faces_w2.png");
	public static final Identifier CHIPS = Burmaldaholic.id("textures/entity/core/board/chips_w.png");
	public static final Identifier BACKING = Burmaldaholic.id("textures/entity/core/board/holo_backing.png");
	public static final int CARD_W = 37, CARD_H = 49, FACES_W = 512, FACES_H = 256;
	public static final int CHIPS_W = 128, CHIPS_H = 64, CHIP_TOP = 16, CHIP_BAND = 4;
	/** Back rows (design index in row 4). */
	public static final int BACK_NAVY = 0, BACK_BURGUNDY = 1, BACK_CRIMSON = 2, BACK_EMERALD = 3, BACK_BASTION = 4, BACK_END = 5;
	public static final String[] THEMES = {"village", "bastion", "end"};

	private static final Identifier[][] FELT = new Identifier[BoardGeometry.Felt.values().length][THEMES.length];
	private static final Identifier[] RAIL = new Identifier[THEMES.length];

	static {
		for (BoardGeometry.Felt f : BoardGeometry.Felt.values()) {
			for (int t = 0; t < THEMES.length; t++) {
				FELT[f.ordinal()][t] = Burmaldaholic.id("textures/entity/core/board/felt_w_" + f.id + "_" + THEMES[t] + ".png");
			}
		}
		for (int t = 0; t < THEMES.length; t++) RAIL[t] = Burmaldaholic.id("textures/entity/core/board/rail_w_" + THEMES[t] + ".png");
	}

	/** Furniture themes of the multi-block tables (MT {@code furniture.mjs}): the print decal matches their felt. */
	public static final String[] FURNITURE = {"standard", "high_roller", "player_banked"};
	/** Shapes of the full-table felt print ({@code TableGame.FeltShape}). */
	public static final String[] PRINT_SHAPES = {"crescent", "oval", "rect", "roulette"};
	private static final Identifier[][] PRINT = new Identifier[PRINT_SHAPES.length][FURNITURE.length];

	static {
		for (int sh = 0; sh < PRINT_SHAPES.length; sh++) {
			for (int t = 0; t < FURNITURE.length; t++) {
				PRINT[sh][t] = Burmaldaholic.id("textures/entity/core/board/felt_print_" + PRINT_SHAPES[sh] + "_" + FURNITURE[t] + ".png");
			}
		}
	}

	private BoardTextures() {}

	/**
	 * {@code felt_print_<shape>_<furniture>.png}: the hi-res felt of a full table (64 texels per block over the
	 * {@code FeltFrame}, inside the rail): baize grain in the furniture's felt colours, a soft edge shade and the printed
	 * lines; transparent outside the rounded felt.
	 */
	public static Identifier print(dev.nezo.burmaldaholic.core.table.parts.TableGame.FeltShape shape, int furniture) {
		return PRINT[shape.ordinal()][furniture < 0 || furniture >= FURNITURE.length ? 0 : furniture];
	}

	public static Identifier felt(BoardGeometry.Felt f, int theme) {
		return FELT[f.ordinal()][clampTheme(theme)];
	}

	public static Identifier rail(int theme) {
		return RAIL[clampTheme(theme)];
	}

	private static int clampTheme(int theme) {
		return theme < 0 || theme >= THEMES.length ? 0 : theme;
	}

	/** Writes (u0, v0, u1, v1) of card {@code card} (0..51) face into {@code out}. */
	public static void faceUv(int card, float[] out) {
		int rank = (card >> 2) + 2;
		int col = rank == 14 ? 0 : rank - 1;
		int row = card & 3;
		cell(col, row, out);
	}

	/** Writes (u0, v0, u1, v1) of back design {@code back} into {@code out}. */
	public static void backUv(int back, float[] out) {
		cell(Math.max(0, Math.min(5, back)), 4, out);
	}

	private static void cell(int col, int row, float[] out) {
		out[0] = col * CARD_W / (float) FACES_W;
		out[1] = row * CARD_H / (float) FACES_H;
		out[2] = (col + 1) * CARD_W / (float) FACES_W;
		out[3] = (row + 1) * CARD_H / (float) FACES_H;
	}
}
